function squadPanel(){if(!S)return;showDialog(panelHead('诸界军令 · 单控与编队')+'<p>点击角色或队员头像单独控制；按住 Shift 点击角色追加选择；在空地拖动框选。点击地面移动，右键地面进攻移动。WASD 只操控当前主将，其他角色遵循各自命令。</p><div class="actions"><button id="selectArmy">全选已加入伙伴</button><button id="holdArmy">选中成员驻守</button><button id="followArmy">选中成员跟随主将</button></div><label>阵型 <select id="formation"><option value="wedge">楔形</option><option value="line">横队</option><option value="circle">环形</option></select></label><div class="group-grid">'+[0,1,2].map(i=>`<article><b>编队 ${i+1}</b><p>${savedGroups[i].length?savedGroups[i].map(n=>HEROES[n].name).join('、'):'尚未保存'}</p><button data-savegroup="${i}">保存当前选择</button><button data-loadgroup="${i}">选中此编队</button></article>`).join('')+'</div><p>Ctrl+1/2/3 保存编队，1/2/3 优先召回已保存编队。未保存时数字键仍为单选英雄；4、5 选择对应英雄。编队与单人命令不会改变技能所属角色。</p>');$('#formation').value=formation;$('#formation').onchange=e=>{formation=e.target.value;S.formation=formation;refreshOrderBar()};$('#selectArmy').onclick=()=>{selectUnits(actors.filter(a=>owned(a.i)).map(a=>a.i));squadPanel()};$('#holdArmy').onclick=()=>{commandUnits('hold');closeDialog()};$('#followArmy').onclick=()=>{commandUnits('follow');closeDialog()};$('#dialog').querySelectorAll('[data-savegroup]').forEach(b=>b.onclick=()=>{saveGroup(+b.dataset.savegroup);squadPanel()});$('#dialog').querySelectorAll('[data-loadgroup]').forEach(b=>b.onclick=()=>{recallGroup(+b.dataset.loadgroup);closeDialog()})}
function worldPoint(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*VW+cam.x,y:(e.clientY-r.top)/r.height*VH+cam.y}}
canvas.addEventListener('pointerdown',e=>{if(!S||menu)return;e.stopImmediatePropagation();if(e.button===2)return;const p=worldPoint(e);selectionDrag={start:p,end:p,shift:e.shiftKey};canvas.setPointerCapture?.(e.pointerId);canvas.focus({preventScroll:true})},true);
canvas.addEventListener('pointermove',e=>{if(selectionDrag)selectionDrag.end=worldPoint(e)});
canvas.addEventListener('pointerup',e=>{if(!selectionDrag)return;const box=selectionDrag;selectionDrag=null;if(dist(box.start,box.end)>24){const minX=Math.min(box.start.x,box.end.x),maxX=Math.max(box.start.x,box.end.x),minY=Math.min(box.start.y,box.end.y),maxY=Math.max(box.start.y,box.end.y);const ids=actors.filter(a=>owned(a.i)&&a.x>=minX&&a.x<=maxX&&a.y>=minY&&a.y<=maxY).map(a=>a.i);selectUnits(box.shift?[...selection,...ids]:ids)}else{const hit=actors.find(a=>owned(a.i)&&a.hp>0&&dist(a,box.end)<32);if(hit)selectUnits(box.shift?[...selection,hit.i]:[hit.i]);else{commandUnits(commandMode,box.end);commandMode='move'}}});
canvas.addEventListener('contextmenu',e=>{e.preventDefault();if(S&&!menu)commandUnits('attackmove',worldPoint(e))});
window.addEventListener('keydown',e=>{if(!S||menu||e.target instanceof HTMLInputElement||e.target instanceof HTMLSelectElement)return;if(/^Digit[1-3]$/.test(e.code)){const n=+e.code.slice(-1)-1;if(e.ctrlKey||e.metaKey){e.preventDefault();e.stopImmediatePropagation();saveGroup(n)}else if(savedGroups[n].length){e.preventDefault();e.stopImmediatePropagation();recallGroup(n)}}if(e.code==='KeyT'){e.preventDefault();ascensionSkill()}},true);
const makeV4Enemy=makeEnemy;makeEnemy=function(z,boss,x,y,id){const e=makeV4Enemy(z,boss,x,y,id);e.map=z+1;const mean=S?S.heroes.filter(h=>h.unlocked).reduce((v,h)=>v+h.lv,0)/S.heroes.filter(h=>h.unlocked).length:1;e.level=Math.max(MAPS[z+1].level,Math.floor(mean*.75));const factor=Math.pow(1+e.level*.085,1.5);e.hp=e.max=Math.round(e.max*factor);e.atk*=1+e.level*.085;return e};
makeWorld=function(){enemies=[];effects=[];numbers=[];loot=[];for(let z=0;z<5;z++){for(let j=0;j<45;j++){const p=j<12?{x:800+(j%4)*170,y:850+Math.floor(j/4)*170}:j<25?{x:2050+(j%5)*130,y:1000+Math.floor((j-12)/5)*240}:{x:3130+(j%5)*160,y:1050+Math.floor((j-25)/5)*340};enemies.push(makeEnemy(z,false,p.x,p.y,j))}const b=makeEnemy(z,true,ZONES[z].x,ZONES[z].y,99);b.repeat=!!S.bosses[z];enemies.push(b)}for(let j=0;j<42;j++){const e=makeEnemy(j%5,j===41, j===41?3850:2200+(j%7)*230,j===41?2100:900+Math.floor(j/7)*240,'rift'+j);e.map=6;e.rift=true;e.level=Math.max(100,Math.max(...S.heroes.map(h=>h.lv))+5);e.hp=e.max=Math.round((j===41?18000:700)*Math.pow(1+e.level*.08,1.45));e.atk=(j===41?85:18)*(1+e.level*.12);enemies.push(e)}};
const previousBegin=begin;begin=function(data){const copy=JSON.parse(JSON.stringify(data));if(!Number.isInteger(copy.map))copy.map=0;for(const h of copy.heroes){h.job=h.job??-1;h.ascensionCd=0}previousBegin(copy);S.map=copy.map;S.fieldTasks=S.fieldTasks||FIELD_TASKS.map((_,i)=>({seen:[],done:false,stage:0}));selection=[S.active];savedGroups=S.groups||[[],[],[]];formation=S.formation||'wedge';for(let a of actors){a.order={kind:a.i===S.active?'hold':'follow'};a.path=[]}loadMapDecor();if(!walkable(active().x,active().y))for(let a of actors){a.x=360+a.i*38;a.y=420}refreshOrderBar();logMessage('诸界远征：传送门通向独立大地图，Ctrl+数字保存编队；100级可转职。')};
const v4SaveValidator=validateSave;validateSave=function(v){if(!v4SaveValidator(v))return false;if(v.map!==undefined&&(!Number.isInteger(v.map)||v.map<0||v.map>=MAPS.length))return false;if(v.groups!==undefined&&(!Array.isArray(v.groups)||v.groups.length!==3||v.groups.some(g=>!Array.isArray(g)||g.length>5||g.some(i=>!Number.isInteger(i)||i<0||i>4))))return false;if(v.heroes.some(h=>h.job!==undefined&&(![-1,0,1].includes(h.job)||h.job>=0&&h.lv<100)))return false;return !v.pets.some(p=>p.fusion!==undefined&&(!p.fusion||!Array.isArray(p.fusion.parents)||p.fusion.parents.length!==2||p.fusion.parents.some(n=>!Number.isInteger(n)||n<0||n>=PETS.length)||!Number.isInteger(p.fusion.stars)||p.fusion.stars<1||p.fusion.stars>3))};
function loadMapDecor(){decor.length=0;for(let i=0;i<720;i++){const x=90+((i*569+currentMap()*311)%4580),y=170+((i*937+currentMap()*173)%2850);if(!walkable(x,y,50)||x<1200&&y<850)continue;decor.push({x,y,type:currentMap()===1||currentMap()===0?i%7:3+i%4,scale:.7+(i%5)*.14})}}
function enterMap(id,force=false){if(!S||!mapUnlocked(id)){logMessage(id===6?'裂隙需要任意英雄达到30级或完成主线。':'先完成前一张地图的守护者。');return false}if(!force&&enemies.some(e=>e.map===currentMap()&&!e.dead&&e.aggro>0&&dist(e,active())<350)){logMessage('脱离战斗后再传送。');return false}S.map=id;for(let a of actors){a.x=360+a.i*40;a.y=440;a.path=[];a.order={kind:a.i===S.active?'hold':'follow'}}destination=null;hazards=[];effects=[];battleFx=[];numbers=[];novaFx=[];cam.x=0;cam.y=0;S.position={x:active().x,y:active().y};loadMapDecor();saveGame(false);refreshBars();logMessage('已传送：'+MAPS[id].name);return true}
function resetDungeon(){if(!currentMap()){logMessage('进入元素地图或裂隙后才能重置。');return false}if(!atCamp()){logMessage('请回到当前地图入口的安全营地后重置。');return false}const id=currentMap(),others=enemies.filter(e=>e.map!==id);makeWorld();enemies=[...others,...enemies.filter(e=>e.map===id)];S.dungeonRuns=(S.dungeonRuns||0)+1;enterMap(id,true);logMessage('本地图怪物与首领已重置；主线奖励不会重复发放。');return true}
function worldPanel(){if(!S)return;showDialog(panelHead('诸界之门 · 七张独立地图')+'<p>每张地图 4800 × 3200；河谷、桥梁、遗迹和城墙形成不同路线。入口是安全区，F 与传送门互动。主线地图按章节开放，30级解锁终局裂隙。</p><div class="world-cards">'+MAPS.map((m,i)=>`<article style="--map:${m.accent}"><small>${i===currentMap()?'当前所在地':mapUnlocked(i)?'传送已解锁':'尚未解锁'}</small><h3>${m.name}</h3><p>${m.desc}</p><b>${i?'推荐 '+m.level+'级起':'安全营地'}</b><button data-map="${i}" ${mapUnlocked(i)?'':'disabled'}>传送</button></article>`).join('')+'</div><div class="actions"><button id="resetDungeon">重置当前副本</button></div>');$('#dialog').querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>{if(enterMap(+b.dataset.map))closeDialog()});$('#resetDungeon').onclick=()=>{if(resetDungeon())closeDialog()}}
const oldReturnCamp=returnCamp;returnCamp=function(force=false){if(!S)return;if(!force&&enemies.some(e=>e.map===currentMap()&&!e.dead&&e.aggro>0&&dist(active(),e)<400)){logMessage('战斗中无法回营。');return}enterMap(0,true);oldReturnCamp(true)};
atCamp=function(){return !!S&&dist(active(),CAMP)<275};
const fieldInteractV4=fieldInteract;fieldInteract=function(){if(currentMap()!==S.chapter+1)return false;return fieldInteractV4()};
const interactV4=interact;interact=function(){if(!S||menu)return;const p=mapPortals().find(p=>dist(active(),p)<105);if(p){enterMap(p.to);return}const chest=CHESTS.findIndex(c=>c.z+1===currentMap()&&dist(active(),c)<100);if(chest>=0&&!S.chests.includes(chest)){S.chests.push(chest);S.gold+=140+chest*80;addItem(chest,true);addPet(5+chest);saveGame(false);refreshBars();logMessage('异界珍藏：金币、装备与稀有灵兽契约！');return}if(atCamp()){interactV4();return}if(!fieldInteract())logMessage('F 可与光圈任务、宝箱或传送门互动。')};$('#touchInteract').onclick=interact;
const statsV4=stats;stats=function(i){const st=statsV4(i),h=S.heroes[i],pet=petOf(i);if(h.job>=0){const support=h.job===1;st.atk=Math.round(st.atk*(support?1.15:1.38));st.spell+=Math.round(st.int*(support?.45:.2));st.hp=Math.round(st.hp*(support?1.35:1.2));st.armor+=support?12:5}if(pet?.fusion){const stars=pet.fusion.stars;st.hp=Math.round(st.hp*(1+stars*.08));st.atk=Math.round(st.atk*(1+stars*.06));st.spell+=stars*14}return st};
needXp=function(lv){return Math.round(60+lv*35+lv*lv*1.2)};
awardXp=function(amount){for(let i=0;i<5;i++)if(owned(i)){const h=S.heroes[i],cap=h.job>=0?150:100;h.xp+=Math.round(amount*(3+h.lv*.22)*(currentMap()===6?1.7:1));while(h.lv<cap&&h.xp>=needXp(h.lv)){h.xp-=needXp(h.lv);h.lv++;h.points+=3;actors[i].hp=stats(i).hp;actors[i].mp=stats(i).mp;novaFx.push({x:actors[i].x,y:actors[i].y,t:1.2,max:1.2,element:i,r:85,kind:'level'});logMessage(HEROES[i].name+' 升至 '+h.lv+' 级！'+(h.lv===100?'可前往转职面板选择职业。':''))}if(h.lv===cap)h.xp=Math.min(h.xp,needXp(h.lv)-1);const pet=petOf(i);if(pet){pet.xp+=Math.round(amount*(2+pet.lv*.12));while(pet.lv<150&&pet.xp>=petNeed(pet.lv)){pet.xp-=petNeed(pet.lv);pet.lv++}}}};
const killV4=kill;kill=function(e,source){const already=e.dead,riftBoss=e.rift&&e.boss;if(riftBoss)e.boss=false;killV4(e,source);if(riftBoss){e.boss=true;e.respawn=80;awardXp(1400);addItem(4,true)}if(!already&&e.dead&&!e.noRewards){if(e.boss&&!e.rift){S.gold+=200+e.z*100;addPet(5+e.z)}else if(Math.random()<.035)addPet(Math.min(11,5+Math.floor(Math.random()*7)));if(e.rift)S.gold+=18}return e.dead};
function promoteHero(i,branch){const h=S.heroes[i];if(!owned(i)||h.lv<100||h.job>=0||![0,1].includes(branch))return false;h.job=branch;h.points+=20;actors[i].hp=stats(i).hp;actors[i].mp=stats(i).mp;novaFx.push({x:actors[i].x,y:actors[i].y,t:2,max:2,element:i,r:180,kind:'ascend'});saveGame(false);refreshBars();logMessage(HEROES[i].name+' 转职为 '+CAREERS[i][branch]+'，等级上限提升至150！');return true}
function careerPanel(){if(!S)return;const i=S.active,h=S.heroes[i];showDialog(panelHead('百级觉醒 · '+HEROES[i].name)+`<p>当前 Lv.${h.lv} · ${h.job>=0?CAREERS[i][h.job]:'尚未转职'}。达到100级可选择一次职业分支，等级保持100级，上限提高至150，并获得20点属性。T 释放觉醒技。</p><div class="career-cards">${CAREERS[i].map((name,k)=>`<article><div class="career-sigil" style="--hero:${HEROES[i].color}">${HEROES[i].element}</div><h3>${name}</h3><p>${k===0?'主攻分支：攻击提高38%，生命提高20%，觉醒技强化爆发。':'守护分支：攻击提高15%，生命提高35%，护甲+12，增强法强与团队护盾。'}</p><button data-career="${k}" ${h.lv<100||h.job>=0?'disabled':''}>选择此职业</button></article>`).join('')}</div><p>觉醒技：45秒冷却，消耗90法力；造成大范围属性伤害，守护分支同时为小队提供护盾。职业选择完成后不能再次更换。</p>`);$('#dialog').querySelectorAll('[data-career]').forEach(b=>b.onclick=()=>{const branch=+b.dataset.career;showDialog(panelHead('确认转职为 '+CAREERS[i][branch]+'？')+'<p>保留等级、宠物和装备。此职业选择不会自动重置。</p><button id="confirmCareer" class="primary">确认觉醒</button>');$('#confirmCareer').onclick=()=>{promoteHero(i,branch);closeDialog()}})}
function ascensionSkill(){if(!S||menu)return false;const a=active(),h=S.heroes[a.i];if(h.job<0){logMessage('英雄100级转职后可解锁觉醒技。');return false}if(h.ascensionCd>0||a.mp<90||a.hp<=0)return false;h.ascensionCd=45;a.mp-=90;a.anim='cast';a.animT=1.1;const st=stats(a.i),targets=enemies.filter(e=>e.map===currentMap()&&!e.dead&&dist(e,a)<470&&(!e.boss||e.rift||S.kills[e.z]>=ZONES[e.z].need));for(const e of targets)enemyDamage(e,(st.atk*7+st.int*14)*(h.job===0?1.35:1),a.i,a.i);if(h.job===1)for(const b of actors)if(owned(b.i))shield(b,st.hp*.35,10);novaFx.push({x:a.x,y:a.y,t:2,max:2,element:a.i,r:470,kind:'ultimate'});screenShake=9;tone(85,.4,'sawtooth');return true}
function fusionResult(a,b){const types=[a.type,b.type];return types.includes(3)&&types.includes(4)?12:types.includes(1)&&types.includes(2)?13:14}
function fusePets(idA,idB){const a=S.pets.find(p=>p.id===idA),b=S.pets.find(p=>p.id===idB);if(!a||!b||a===b||a.lv<10||b.lv<10||S.gold<250)return null;const type=fusionResult(a,b),stars=Math.min(3,Math.max(a.fusion?.stars||0,b.fusion?.stars||0)+1),result={id:Math.max(100,...S.pets.map(p=>p.id))+1,type,lv:Math.max(1,Math.floor((a.lv+b.lv)/2)),xp:0,fusion:{parents:[a.type,b.type],stars}};S.gold-=250;const activeConsumed=[idA,idB].includes(S.heroes[S.active].pet);for(const h of S.heroes)if(h.pet===idA||h.pet===idB)h.pet=null;S.pets=S.pets.filter(p=>p.id!==idA&&p.id!==idB);S.pets.push(result);if(activeConsumed||S.heroes[S.active].pet===null)S.heroes[S.active].pet=result.id;for(const actor of actors){actor.hp=Math.min(actor.hp,stats(actor.i).hp);actor.mp=Math.min(actor.mp,stats(actor.i).mp)}saveGame(false);refreshBars();logMessage('合体成功：'+PETS[type].name+' · '+stars+'星');return result}
function petArtType(type){return type===12?3:type===13?1:type===14?11:type}
function petCardStyle(type){if(type>=12)return `background-image:var(--fusion-atlas);background-size:300% 100%;background-position:${(type-12)*50}% 0%`;const n=petArtType(type);return `background-image:var(--pet-atlas);background-size:400% 300%;background-position:${n%4*100/3}% ${Math.floor(n/4)*50}%`}
addPet=function(type,announce=true){if(!PETS[type])return null;const old=S.pets.find(p=>p.type===type&&!p.fusion);if(old){if(old.lv<150)old.lv++;if(announce)logMessage('重复契约提升 '+PETS[type].name+' 至 '+old.lv+'级。');return old}if(S.pets.length>=100){logMessage('灵兽栏已满，请先整理合体。');return null}const p={id:Math.max(0,...S.pets.map(v=>v.id))+1,type,lv:1,xp:0};S.pets.push(p);if(S.heroes[S.active].pet===null)S.heroes[S.active].pet=p.id;if(announce)logMessage('获得灵兽：'+PETS[type].name);return p};
function fusionPanel(){if(!S)return;const available=S.pets.filter(p=>p.lv>=10);showDialog(panelHead('灵兽合体 · 双魂共鸣')+'<p>两只不同的10级以上灵兽 + 250金币，可合体为新灵兽。材料灵兽会消耗，其骑乘者自动解除绑定；结果保留两者平均等级。合体最高3星。</p><p>青龙 + 朱雀 → 龙凰天灵；白虎 + 玄武 → 玄虎战魂；其他组合 → 星灵合兽。</p><div class="fusion-select"><label>材料一<select id="fusionA">'+available.map(p=>`<option value="${p.id}">${PETS[p.type].name} Lv.${p.lv}</option>`).join('')+'</select></label><span>✦</span><label>材料二<select id="fusionB">'+available.map(p=>`<option value="${p.id}">${PETS[p.type].name} Lv.${p.lv}</option>`).join('')+'</select></label></div><div id="fusionPreview"></div><div class="actions"><button id="fusionConfirm" class="primary" '+(available.length<2?'disabled':'')+'>预览合体</button><button id="backPets">返回灵兽</button></div>');if(available.length>1)$('#fusionB').value=available[1].id;$('#backPets').onclick=petsPanel;$('#fusionConfirm').onclick=()=>{const a=S.pets.find(p=>p.id===+$('#fusionA').value),b=S.pets.find(p=>p.id===+$('#fusionB').value);if(!a||!b||a.id===b.id){$('#fusionPreview').textContent='请选择两只不同的灵兽。';return}const type=fusionResult(a,b);showDialog(panelHead('确认消耗两只灵兽？')+`<div class="fusion-result" style="${petCardStyle(type)}"></div><h3>${PETS[type].name}</h3><p>消耗 ${PETS[a.type].name} Lv.${a.lv}、${PETS[b.type].name} Lv.${b.lv} 与250金币。结果等级 ${Math.floor((a.lv+b.lv)/2)}。当前金币 ${S.gold}。</p><button id="doFusion" class="primary" ${S.gold<250?'disabled':''}>确认合体</button><button id="cancelFusion">返回选择</button>`);$('#cancelFusion').onclick=fusionPanel;$('#doFusion').onclick=()=>{if(fusePets(a.id,b.id))petsPanel()}}}
petsPanel=function(){if(!S)return;showDialog(panelHead('灵兽殿 · 十二种族与合体')+`<p>已收集 ${S.pets.length} 只灵兽 · 金币 ${S.gold}。重复契约提升原种等级；战斗成长达到10级后可参与合体。普通种族12种，另有3类合体灵兽。</p><div class="actions"><button id="openFusion" class="primary">灵兽合体</button></div><div class="pet-grid">`+PETS.map((p,type)=>{const ownedPets=S.pets.filter(v=>v.type===type);return `<article><div class="pet-portrait" style="${petCardStyle(type)}"></div><h3>${p.name}</h3><p>${p.bonus}</p>${ownedPets.map(pet=>`<p>Lv.${pet.lv} ${pet.fusion?'✦'.repeat(pet.fusion.stars):''}</p><select data-assignpet="${pet.id}"><option value="-1">不骑乘</option>${HEROES.map((h,i)=>owned(i)?`<option value="${i}" ${S.heroes[i].pet===pet.id?'selected':''}>${h.name}</option>`:'').join('')}</select>`).join('')}${!ownedPets.length?'<small>尚未收集</small>':''}${type<12?`<button data-petbuy="${type}" ${!atCamp()||type>4&&S.chapter<Math.min(4,type-5)?'disabled':''}>契约 ${150+type*115}金</button>`:'<small>通过双宠合体获得</small>'}</article>`}).join('')+'</div>');$('#openFusion').onclick=fusionPanel;$('#dialog').querySelectorAll('[data-assignpet]').forEach(b=>b.onchange=()=>{const id=+b.dataset.assignpet;for(const h of S.heroes)if(h.pet===id)h.pet=null;if(+b.value>=0)S.heroes[+b.value].pet=id;for(const a of actors){a.hp=Math.min(a.hp,stats(a.i).hp);a.mp=Math.min(a.mp,stats(a.i).mp)}saveGame(false);refreshBars()});$('#dialog').querySelectorAll('[data-petbuy]').forEach(b=>b.onclick=()=>{const type=+b.dataset.petbuy,cost=150+type*115;if(!atCamp()||S.gold<cost){logMessage('请在营地交易，并准备足够金币。');return}S.gold-=cost;addPet(type);saveGame(false);petsPanel();refreshBars()})};
// A separate order-driven update keeps unselected heroes at their own positions.
baseUpdate=function(dt){if(!S||menu)return;time+=dt;S.played+=dt;const leader=active(),dx=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),dy=(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0);
 if(dx||dy){leader.path=[];leader.order={kind:'hold'};destination=null;move(leader,dx,dy,stats(leader.i).speed,dt)}else if(destination){const target={...destination};destination=null;commandUnits(commandMode,target);commandMode='move'}
 for(const a of actors){if(!owned(a.i))continue;const h=S.heroes[a.i],st=stats(a.i);h.ascensionCd=Math.max(0,(h.ascensionCd||0)-dt);if(a.hp<=0){a.down-=dt;if(a.down<=0){a.hp=st.hp*.5;a.mp=st.mp*.5;a.inv=2}continue}a.inv=Math.max(0,a.inv-dt);a.attack=Math.max(0,a.attack-dt);a.cd=a.cd.map(v=>Math.max(0,v-dt));a.shieldTime=Math.max(0,a.shieldTime-dt);if(!a.shieldTime)a.shield=0;const safe=dist(a,CAMP)<275;a.hp=Math.min(st.hp,a.hp+dt*(safe?st.hp*.12:st.hp*.0008));a.mp=Math.min(st.mp,a.mp+dt*(safe?st.mp*.15:1.4+st.int*.085));a.planIn=Math.max(0,(a.planIn||0)-dt);a.order=a.order||{kind:'hold'};
 const threat=nearestEnemy(a,420),order=a.order;if(!(a.i===S.active&&(dx||dy||Math.hypot(joystickVector.x,joystickVector.y)>.1))){if(order.kind==='move'){if(!moveAlong(a,dt))a.order={kind:'hold'}}else if(order.kind==='attackmove'&&a.path?.length){if(threat&&dist(a,threat)<st.range)attack(a);else moveAlong(a,dt)}else if(order.kind==='follow'&&a.i!==S.active){const p=formationOffset(a.i,5),target={x:leader.x+p.x,y:leader.y+p.y};if(threat&&dist(threat,leader)<500){if(dist(a,threat)>st.range*.85){if(a.planIn<=0){a.path=findPath(a,threat);a.planIn=.8}moveAlong(a,dt)}}else if(dist(a,target)>95){if(a.planIn<=0){a.path=findPath(a,target);a.planIn=.6}moveAlong(a,dt)}}}
 const canFight=order.kind!=='move';if(canFight&&(a.i!==S.active||$('#autoAttack').checked||keys.has('KeyJ')))attack(a);if(a.i!==S.active&&canFight){if(threat&&dist(a,threat)<(a.i===0||a.i===4?140:340))skill(a.i,0);if(a.i===1&&actors.some(b=>owned(b.i)&&b.hp>0&&b.hp<stats(b.i).hp*.65))skill(a.i,1);if((a.i===2||a.i===4)&&threat&&a.hp<st.hp*.75)skill(a.i,1)}
 }
 if(menu)return;updateEnemies(dt);for(const list of [effects,numbers,loot])for(const o of list){o.t-=dt;if(list===numbers)o.y-=dt*25}effects=effects.filter(o=>o.t>0);numbers=numbers.filter(o=>o.t>0);loot=loot.filter(o=>o.t>0);cam.x+=(clamp(active().x-VW*.5,0,WW-VW)-cam.x)*Math.min(1,dt*6);cam.y+=(clamp(active().y-VH*.5,0,WH-VH)-cam.y)*Math.min(1,dt*6);hudTime-=dt;if(hudTime<=0){hudTime=.22;refreshBars()}if(time-lastAutoSave>15){lastAutoSave=time;saveGame(false)}};
const updateEnemyV4=updateEnemies;updateEnemies=function(dt){const before=enemies.map(e=>({x:e.x,y:e.y,map:e.map}));for(const e of enemies)if(e.rift&&e.boss&&e.dead){e.respawn-=dt;if(e.respawn<=0&&dist(e,active())>400){e.dead=false;e.hp=e.max;e.phase=1;e.engaged=false}}const kills=S.kills.slice(),oldChapter=S.chapter;if(currentMap()===6)S.chapter=4;if(currentMap()===6)for(let z=0;z<5;z++)S.kills[z]=Math.max(S.kills[z],ZONES[z].need);updateEnemyV4(dt);if(currentMap()===6){S.kills=kills;S.chapter=oldChapter}enemies.forEach((e,i)=>{if(before[i])e.map=before[i].map;if(!e.dead&&!walkable(e.x,e.y,e.boss?35:18)&&before[i]){e.x=before[i].x;e.y=before[i].y}})};
const nearestV4=nearestEnemy;nearestEnemy=function(a,range,includeDormant=false){let target=null,distance=range;for(const e of enemies)if(e.map===currentMap()&&!e.dead&&(e.rift||e.z<=S.chapter||S.won)&&(!e.boss||includeDormant||e.rift||S.kills[e.z]>=ZONES[e.z].need)){const d=dist(a,e);if(d<distance){distance=d;target=e}}return target};
const damageV4=enemyDamage;enemyDamage=function(e,...args){if(e.map!==currentMap())return;if(e.rift){const old=S.kills[e.z],chapter=S.chapter;S.kills[e.z]=Math.max(old,ZONES[e.z].need);S.chapter=4;try{return damageV4(e,...args)}finally{S.kills[e.z]=old;S.chapter=chapter}}return damageV4(e,...args)};
const updateV4=update;update=function(dt){if(!S||menu)return;const all=enemies;enemies=all.filter(e=>e.map===currentMap());try{updateV4(dt);for(const e of enemies)if(e.map===undefined)e.map=currentMap();const additions=enemies.filter(e=>!all.includes(e));all.push(...additions)}finally{enemies=all}for(const a of actors)if(a.hp>0&&!walkable(a.x,a.y)){a.x=360+a.i*40;a.y=440;a.path=[]}for(const e of novaFx)e.t-=dt;novaFx=novaFx.filter(e=>e.t>0).slice(-18);const portal=mapPortals().find(p=>dist(active(),p)<115);if(portal)$('#hint').textContent='F 传送 · '+MAPS[portal.to].name;else if(currentMap()===0)$('#hint').textContent='点击「传送」选择地图；或走近诸界之门按 F。';else if(currentMap()!==S.chapter+1)$('#hint').textContent=MAPS[currentMap()].desc};
const castV4=skill;skill=function(i,slot,manual=false){const all=enemies;enemies=all.filter(e=>e.map===currentMap());let result;try{result=castV4(i,slot,manual)}finally{enemies=all}if(result){const a=actors[i],target=nearestEnemy(a,500);novaFx.push({x:target?.x||a.x,y:target?.y||a.y,t:slot===2?1.7:.95,max:slot===2?1.7:.95,element:i,r:slot===2?300:140,kind:slot===2?'ultimate':'spell'});if(S.heroes[i].job>=0){if(S.heroes[i].job===0&&target)enemyDamage(target,stats(i).atk*1.1,i,i);else shield(a,stats(i).int*2,4)}}return result};
const tellResolveV4=resolveBossTell;resolveBossTell=function(e){if(e.wind)novaFx.push({x:e.wind.x,y:e.wind.y,t:1.4,max:1.4,element:e.element,r:e.wind.r,kind:'boss'});tellResolveV4(e)};
const v4Refresh=refreshBars;refreshBars=function(){v4Refresh();if(!S)return;const m=MAPS[currentMap()],h=S.heroes[S.active];$('#zoneName').innerHTML=m.name+' <small>'+(atCamp()?'入口安全区':m.desc)+'</small>';$('#chapterLabel').textContent='诸界 '+currentMap()+'/6 · '+m.name;$('#objective').textContent=currentMap()===0?'整备小队，通过传送门进入独立地图':currentMap()===6?'挑战高等级裂隙守卫，收集装备与经验':S.bosses[currentMap()-1]?'守护者已击败，可在入口重置副本重刷战利品':`清理 ${Math.min(S.kills[currentMap()-1],ZONES[currentMap()-1].need)} / ${ZONES[currentMap()-1].need} 妖兽，解除首领屏障`;$('#heroDetail').innerHTML+=`<br><span class="job-label">${h.job>=0?CAREERS[S.active][h.job]:'100级可转职'} · 觉醒技 T ${h.ascensionCd>0?Math.ceil(h.ascensionCd)+'s':''}</span>`;const boss=enemies.find(e=>e.map===currentMap()&&e.boss&&!e.dead&&dist(active(),e)<540);$('#bossHud').classList.toggle('hidden',!boss);if(boss)$('#bossHud').innerHTML=(boss.rift?'星渊守门人':ZONES[boss.z].boss)+` <small>Lv.${boss.level} · 阶段 ${boss.phase}/3</small><div class="bar"><b style="width:${clamp(boss.hp/boss.max*100,0,100)}%"></b></div>`;refreshOrderBar()};
// Equipment uses painted item cards, with optional unobtrusive in-world quality glow.
const GEAR_COL=[0,1,2,3,4,5];
