 ['q','e','r'].forEach((key,n)=>{$('#label6-'+n).textContent=d[key];$('#action6-'+n).title=d.skills[n]});$('#label6-potion').textContent='药剂 '+S.potions;$('#petAction').textContent=pet?(a.petCd>0?'灵兽 '+Math.ceil(a.petCd)+'s':'灵兽技 V'):'未骑乘';$('#petAction').disabled=!pet||a.petCd>0;
